// Demo mode v3 cases (generated by scripts/sync-fixtures.mjs from the real fixtures, no NEAR AI calls).
import { describe, expect, it } from 'vitest';
import demo from '../fixtures/demo.json';
import { buildDemo, DEMO_FRONTRUNNER, DEMO_RESP_BODIES, DEMO_SIGNERS } from './demo';
import { decryptReport, parseOwnerSecret, proveCiphertext } from './crypto';
import { auditRequest } from './requestChecks';
import { checkRequestAgainstProgram, paramsHash } from '@sealedbounty/shared';
import { verifyClaim } from './checks';
import { sha256hex } from './verify';
import type { Claim } from './types';

const NOW = 1_800_000_000_000;
const { programs, claims } = buildDemo(NOW);
const { secretKey } = parseOwnerSecret(JSON.stringify(demo.owner_secret));
const decrypt = (c: Claim) => decryptReport(c.ciphertext, secretKey);
const prog = (c: Claim) => programs.find((p) => p.id === c.program_id)!;
const ms = (ns: string) => Number(BigInt(ns) / 1_000_000n);
const byReason = (r: string) => claims.filter((c) => c.reject_reason === r);

describe('demo programs are v3', () => {
  it('pin params_hash, their own signer set, a bond and a challenge window', () => {
    expect(programs.length).toBeGreaterThanOrEqual(2);
    for (const p of programs) {
      expect(p.params_hash).toBe(paramsHash());
      expect(p.signers).toEqual(DEMO_SIGNERS.map((s) => s.signer));
      expect(BigInt(p.bond!)).toBeGreaterThan(0n);
      expect(p.challenge_secs).toBeGreaterThan(0);
    }
  });

  it('every onchain claim holds the program bond', () => {
    for (const c of claims.filter((x) => !x.refused_at_submit)) expect(c.bond).toBe(prog(c).bond);
  });

  it('pool accounting: balance + reserved + paid = funded + forfeited bonds', () => {
    for (const p of programs) {
      const mine = claims.filter((c) => c.program_id === p.id && !c.refused_at_submit);
      const paid = mine.filter((c) => c.status === 'Paid').reduce((a, c) => a + BigInt(c.payout), 0n);
      const held = mine.filter((c) => c.status === 'Pending' || c.status === 'Challenged').reduce((a, c) => a + BigInt(c.payout), 0n);
      const forfeited = mine.filter((c) => c.status === 'Rejected').reduce((a, c) => a + BigInt(c.bond!), 0n);
      expect(BigInt(p.reserved)).toBe(held);
      expect(BigInt(p.balance) + held + paid - forfeited).toBe(100n * 10n ** 24n);
    }
  });
});

describe('existing demo cases are kept', () => {
  it('front-run, sqli paid, fakecode, idor pending, 2 refused', () => {
    expect(claims.find((c) => c.hunter === DEMO_FRONTRUNNER)?.reject_reason).toBe('hunter mismatch');
    expect(byReason('code mismatch')).toHaveLength(1);
    expect(claims.filter((c) => c.refused_at_submit)).toHaveLength(2);
    expect(claims.find((c) => c.program_id === 0 && c.req_hash === demo.cases.sqli.req_hash && c.status === 'Paid')).toBeTruthy();
    expect(claims.find((c) => c.program_id === 0 && c.req_hash === demo.cases.idor.req_hash)?.status).toBe('Pending');
  });
});

describe('v3 case: params tampered', () => {
  const [c] = byReason('params tampered');
  it('is a Rejected, synthetic claim derived from the sqli fixture', () => {
    expect(c).toBeTruthy();
    expect(c.status).toBe('Rejected');
    expect(c.synthetic).toMatch(/sqli/);
    expect(demo.v3.params_tampered.base).toBe('sqli');
  });
  it('decrypts to its req_hash and the shared pre-check says "params tampered"', () => {
    const body = decrypt(c);
    expect(sha256hex(body)).toBe(c.req_hash);
    expect(checkRequestAgainstProgram(body, { ...prog(c), code_hash: prog(c).code_hash! }, c.hunter)).toEqual({ ok: false, reason: 'params tampered' });
    expect(auditRequest(body, prog(c), c.hunter).checks.find((x) => x.key === 'params')!.ok).toBe(false);
  });
  it('only the params differ from the honest sqli request', () => {
    const t = JSON.parse(decrypt(c));
    const h = JSON.parse(demo.cases.sqli.request_body);
    expect(t.messages).toEqual(h.messages);
    expect(t.model).toBe(h.model);
    expect(t.response_format).not.toEqual(h.response_format);
  });
});

describe('v3 case: junk ciphertext (decryption challenge)', () => {
  it('one was Challenged and then Rejected "undecryptable report"', () => {
    const [c] = byReason('undecryptable report');
    expect(c.status).toBe('Rejected');
    expect(() => decrypt(c)).toThrow(/decryption failed/);
    expect(c.challenge_deadline).not.toBeNull();
    const ev = c.history!.map((h) => h.event).join(' | ');
    expect(ev).toMatch(/flag_undecryptable.*Challenged.*finalize.*undecryptable report/);
    expect(ms(c.challenge_deadline!)).toBeLessThan(NOW);
  });
  it('one is still Challenged with an open deadline', () => {
    const open = claims.filter((c) => c.status === 'Challenged');
    expect(open).toHaveLength(1);
    expect(ms(open[0].challenge_deadline!)).toBeGreaterThan(NOW);
    expect(() => decrypt(open[0])).toThrow();
  });
});

describe('v3 case: honest claim challenged, proven, paid', () => {
  const c = claims.find((x) => x.proof_secret)!;
  it('is Paid after flag → prove_ciphertext → finalize', () => {
    expect(c.status).toBe('Paid');
    expect(c.history!.map((h) => h.event).join(' | ')).toMatch(/flag_undecryptable.*prove_ciphertext.*finalize/);
  });
  it('the revealed secret proves the ciphertext in the browser (no owner key needed)', () => {
    expect(proveCiphertext(c.ciphertext, prog(c).owner_enc_pubkey, c.proof_secret!, c.req_hash)).toMatchObject({ ok: true });
    expect(auditRequest(decrypt(c), prog(c), c.hunter).ok).toBe(true);
  });
});

describe('Verified panel on all demo claims', () => {
  it('nothing fails (synthetic signature is n/a, not a fake pass)', () => {
    for (const c of claims) {
      const cs = verifyClaim(c, prog(c), DEMO_SIGNERS, { respBodyB64: DEMO_RESP_BODIES[c.id], signersSource: 'demo', revoked: new Set() });
      expect(cs.filter((x) => x.status === 'fail')).toEqual([]);
      expect(cs.find((x) => x.label.startsWith('TEE signature'))!.status).toBe(c.synthetic ? 'na' : 'pass');
      expect(cs.find((x) => x.label.startsWith('Signer in PROGRAM set'))!.status).toBe('pass');
    }
  });
});
